name: Coordination Label Cleanup

on:
  issues:
    types: [closed]

permissions:
  contents: read
  issues: write

jobs:
  cleanup-active-coordination-labels:
    name: Clear active labels after issue completion
    runs-on: ubuntu-latest
    steps:
      - name: Check out repository
        uses: actions/checkout@v4

- name: Remove active coordination labels
        uses: actions/github-script@v7
        with:
          script: |
            const cleanup = require(`${process.env.GITHUB_WORKSPACE}/.github/scripts/cleanup-coordination-labels`);
            const { data: issue } = await github.rest.issues.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
            });
            const result = await cleanup(issue, async (name) => {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                name,
              });
            });
            if (result.preservedTerminalState) {
              core.info("Issue closed in a terminal blocked state; preserving its labels.");
            }
